import type enDashboard from "@/i18n/en/dashboard";

// Russian plurals (i18next + Intl.PluralRules) need _few and _many next to every _one/_other pair.
type RuPluralKeys<K> = K extends `${infer B}_one` ? `${B}_few` | `${B}_many` : never;

