  'ext_agent_setup_skill': 'Навык настройки',
  'ext_agent_copy_setup_skill': 'Копировать навык настройки',
  'ext_agent_mcp_endpoint': 'Эндпоинт MCP',
  'ext_agent_copy_mcp_endpoint': 'Копировать эндпоинт MCP',
  'ext_agent_step_token_title': 'Подготовьте токен доступа',
  'ext_agent_step_token_desc': 'Навыку настройки также нужен токен доступа. Полный токен показывается только один раз — при создании. Сразу сохраните его и передавайте только внешнему агенту, которому доверяете. Навык настройки сохраняет токен открытым текстом в конфигурацию MCP и в .arcreel/settings.json. Если эти файлы находятся в репозитории кода, добавьте их в .gitignore и прекратите отслеживание тех, что Git уже отслеживает, чтобы токен не попал в коммит.',
  'ext_agent_manage_tokens': 'Управление токенами доступа',
  'ext_agent_prompt_title': 'Пусть ИИ-агент подключится за вас',
  'ext_agent_prompt_desc': 'Отправьте этот промпт своему ИИ-агенту. Он прочитает специальное руководство по установке и проведёт вас через навыки, MCP и проверку подключения.',
  'ext_agent_prompt': 'Помоги мне подключить [[brand]]. Прочитай {{guideUrl}} и следуй инструкциям',
