  'agent_credentials': 'Провайдеры агента',
  'agent_providers_desc': 'Каждый провайдер агента — это шлюз, совместимый с Anthropic. Одновременно активен только один провайдер; после переключения новые сеансы используют новый провайдер, а уже запущенные — прежний.',
  'arcreel_agent_section_desc': 'Агент [[brand]] — творческий агент рабочего пространства. Он обращается к моделям через активного провайдера агента, указанного ниже.',
  'arcreel_agent_external_hint': 'Чтобы внешние агенты, например Claude Code, могли работать с [[brand]], см. <guide>Подключение внешних агентов</guide>.',
  'arcreel_agent_language_rule_hint': 'Языковое правило задаёт язык ответов и результатов агента. Его можно прочитать в разделе <templates>Шаблоны промптов</templates>.',
  'arcreel_agent_advanced': 'Дополнительно',
  'embedded_agent_not_configured': 'Агент [[brand]] не настроен',
  'embedded_agent_not_configured_desc': 'Нет активного провайдера агента, поэтому агент в рабочих пространствах проектов не может общаться. Добавьте провайдера агента, чтобы начать.',
  'cred_multiplier_label': 'Множитель',
  'cred_multiplier_help': 'Применяется к справочной стоимости каждого вызова через этого провайдера агента, чтобы учесть разницу между ценами шлюза и официальными. 1 — без корректировки; для шлюзов по подписке можно указать 0, чтобы не учитывать стоимость. Изменения влияют только на последующие вызовы; уже записанная стоимость не пересчитывается.',
  'cred_multiplier_invalid': 'Множитель должен быть числом не меньше 0.',
